// Studio: collaborative place editor, pro-editor layout.
// Ribbon toolbar · Toolbox + Explorer panel · 3D move/scale gizmos ·
// snap controls · properties · live co-editing · status bar.
import * as THREE from 'three';
import { setupScene, World, createPartMesh } from '../engine/world.js';
import { state, openWS, esc, toast } from '../api.js';
import { icon } from '../icons.js';

const PART_DEFS = [
  { type: 'block',      label: 'Block',      color: '#a8b6bd', size: [4, 1, 4] },
  { type: 'spawn',      label: 'Spawn',      color: '#cfd8dc', size: [6, 0.5, 6] },
  { type: 'checkpoint', label: 'Checkpoint', color: '#19c2ff', size: [3, 0.5, 3] },
  { type: 'kill',       label: 'Kill Brick', color: '#d40000', size: [4, 0.4, 4] },
  { type: 'coin',       label: 'Coin',       color: '#ffd700', size: [1, 1, 1] },
  { type: 'goal',       label: 'Goal',       color: '#19ff8c', size: [4, 1, 4] },
  { type: 'bounce',     label: 'Bounce',     color: '#ffe14d', size: [3, 1, 3] },
  { type: 'speed',      label: 'Speed Pad',  color: '#19c2ff', size: [4, 0.2, 4] },
  { type: 'water',      label: 'Water',      color: '#2a7de1', size: [8, 3, 8] },
  { type: 'deco',       label: 'Deco',       color: '#8d6e63', size: [2, 2, 2] },
  { type: 'mover',      label: 'Mover',      color: '#9b59b6', size: [4, 1, 4] },
  { type: 'tele',       label: 'Teleporter', color: '#8a4fff', size: [3, 0.6, 3] },
];

const COLOR_PALETTE = ['#a8b6bd', '#e54b4b', '#f0a020', '#ffd23f', '#3aa14f', '#19ff8c', '#2a7de1', '#19c2ff', '#8a4fff', '#ff5e9c', '#8d6e63', '#37474f', '#ffffff', '#1b1b1b'];
const MODES = ['sandbox', 'obby', 'collect', 'tag'];
const GENRES = ['Obby', 'Collecting', 'Tag', 'Social', 'Adventure', 'Fighting', 'Tycoon', 'Other'];
const AXIS_COLORS = { x: 0xff4d5e, y: 0x19ff8c, z: 0x19c2ff };

export class Studio {
  constructor(root, gameId, onExit) {
    this.root = root;
    this.gameId = gameId;
    this.onExit = onExit;
    this.tool = 'select';   // select | move | scale | place | delete
    this.placeType = 'block';
    this.snap = 0.5;
    this.selId = null;
    this.editors = new Map();
    this.keys = {};
    this.camPos = new THREE.Vector3(26, 20, 26);
    this.camYaw = Math.PI / 4;
    this.camPitch = -0.5;
    this.alive = true;
    this.undoStack = [];
    this.gizmoDrag = null;
    this._lastOpSend = 0;

    this._buildDOM();
    const { renderer, scene, camera, resize } = setupScene(this.canvas);
    this.renderer = renderer;
    this.scene = scene;
    this.camera = camera;
    this.resizeFn = resize;
    this.world = new World(scene);

    this.ghost = null;
    this.grid = new THREE.GridHelper(140, 70, 0x3a607a, 0x1c2c38);
    this.grid.position.y = 0.01;
    this.grid.material.transparent = true;
    this.grid.material.opacity = 0.3;
    this.grid.material.depthWrite = false;
    this.grid.material.fog = true;
    scene.add(this.grid);

    this.selBox = new THREE.Box3Helper(new THREE.Box3(), 0xffd23f);
    this.selBox.visible = false;
    scene.add(this.selBox);
    this.moverPath = null;

    this._buildGizmo();
    this.raycaster = new THREE.Raycaster();
    this.raycaster.params.Line.threshold = 0.01;

    this._connect();
    this._bindInput();
    this._loop();
  }

  // ================= DOM =================
  _buildDOM() {
    const ribbonBtn = (tool, icn, label, key) => `
      <button class="rb-btn" data-tool="${tool}" title="${label} (${key})">
        <span class="rb-icn">${icon(icn, 20)}</span><span class="rb-label">${label}</span>
      </button>`;
    this.root.innerHTML = `
      <div id="studio-topbar">
        <span class="title">${icon('wrench', 17)} Studio</span>
        <span id="st-gamename" style="color:var(--dim)"></span>
        <span class="spacer"></span>
        <span id="st-editors" class="row" style="gap:6px"></span>
        <button class="tool-btn" id="st-test">${icon('play', 13)} Test</button>
        <button class="tool-btn" id="st-exit">${icon('exit', 14)} Exit</button>
      </div>
      <div id="studio-ribbon">
        <div class="rb-group">
          ${ribbonBtn('select', 'cursor', 'Select', '1')}
          ${ribbonBtn('move', 'move', 'Move', '2')}
          ${ribbonBtn('scale', 'scale', 'Scale', '3')}
          ${ribbonBtn('delete', 'trash', 'Delete', '4')}
          <span class="rb-caption">Tools</span>
        </div>
        <div class="rb-group">
          <button class="rb-btn" id="rb-undo" title="Undo (Ctrl+Z)"><span class="rb-icn">${icon('undo', 20)}</span><span class="rb-label">Undo</span></button>
          <button class="rb-btn" id="rb-dup" title="Duplicate (Ctrl+D)"><span class="rb-icn">${icon('copy', 20)}</span><span class="rb-label">Duplicate</span></button>
          <span class="rb-caption">Edit</span>
        </div>
        <div class="rb-group">
          <div class="rb-snap">
            <label><input type="checkbox" id="rb-snap-on" checked> Snap</label>
            <select id="rb-snap-step">
              <option value="1">1 stud</option>
              <option value="0.5" selected>0.5</option>
              <option value="0.25">0.25</option>
            </select>
          </div>
          <span class="rb-caption">Grid</span>
        </div>
        <div class="rb-group" id="rb-sel-info"><span class="rb-caption">Selection</span></div>
      </div>
      <div id="studio-main">
        <div id="studio-left">
          <h3>${icon('cube', 12)} Toolbox</h3>
          <div class="part-palette" id="st-palette"></div>
          <h3>${icon('search', 12)} Explorer</h3>
          <input type="text" id="st-explorer-q" placeholder="Filter parts…">
          <div id="st-explorer"></div>
        </div>
        <div id="studio-canvas-wrap"><canvas></canvas></div>
        <div id="studio-side">
          <h3>Properties</h3>
          <div id="st-props"><div style="color:var(--dim)">Nothing selected</div></div>
          <h3>Game Config</h3>
          <div id="st-config"></div>
          <h3>Team Chat</h3>
          <div id="studio-chat-log"></div>
          <input id="st-chat-input" type="text" placeholder="Message collaborators…" maxlength="200">
        </div>
      </div>
      <div id="studio-status">
        <span id="sts-parts"></span><span class="sts-sep">·</span>
        <span id="sts-sel">nothing selected</span><span class="sts-sep">·</span>
        <span id="sts-cam"></span>
        <span class="spacer"></span>
        <span class="sts-hint">RMB look · WASD fly · E/Q up/down · Shift fast · F focus · Esc deselect</span>
      </div>
    `;
    this.canvas = this.root.querySelector('canvas');
    this.propsEl = this.root.querySelector('#st-props');
    this.configEl = this.root.querySelector('#st-config');
    this.editorsEl = this.root.querySelector('#st-editors');
    this.explorerEl = this.root.querySelector('#st-explorer');

    const palette = this.root.querySelector('#st-palette');
    for (const def of PART_DEFS) {
      const b = document.createElement('button');
      b.className = 'tool-btn';
      b.textContent = def.label;
      b.style.borderLeft = `4px solid ${def.color}`;
      b.dataset.type = def.type;
      b.onclick = () => { this.placeType = def.type; this.setTool('place'); };
      palette.appendChild(b);
    }
    this.root.querySelectorAll('[data-tool]').forEach((b) => {
      b.onclick = () => this.setTool(b.dataset.tool);
    });
    this.root.querySelector('#rb-undo').onclick = () => this._undo();
    this.root.querySelector('#rb-dup').onclick = () => this._duplicate();
    this.root.querySelector('#rb-snap-on').onchange = (e) => { this.snap = e.target.checked ? Number(this.root.querySelector('#rb-snap-step').value) : 0; };
    this.root.querySelector('#rb-snap-step').onchange = (e) => {
      if (this.root.querySelector('#rb-snap-on').checked) this.snap = Number(e.target.value);
    };
    this.root.querySelector('#st-exit').onclick = () => this.exit();
    this.root.querySelector('#st-test').onclick = () => this.exit('#/play/' + this.gameId);
    this.root.querySelector('#st-explorer-q').addEventListener('input', () => this._renderExplorer());
    this.root.querySelector('#st-explorer-q').addEventListener('keydown', (e) => e.stopPropagation());
    const chatInput = this.root.querySelector('#st-chat-input');
    chatInput.addEventListener('keydown', (e) => {
      e.stopPropagation();
      if (e.key === 'Enter') {
        const text = chatInput.value.trim();
        if (text) this._send({ t: 'chat', text });
        chatInput.value = '';
      }
    });
    this.setTool('select');
  }

  setTool(tool) {
    this.tool = tool;
    this.root.querySelectorAll('[data-tool]').forEach((b) => b.classList.toggle('active', b.dataset.tool === tool));
    this.root.querySelectorAll('#st-palette .tool-btn').forEach((b) => {
      b.classList.toggle('active', tool === 'place' && b.dataset.type === this.placeType);
    });
    if (tool !== 'place' && this.ghost) { this.scene.remove(this.ghost); this.ghost = null; }
    this.canvas.style.cursor = tool === 'delete' ? 'not-allowed' : tool === 'place' ? 'copy' : 'default';
  }

  _snapV(v) {
    return this.snap > 0 ? Math.round(v / this.snap) * this.snap : v;
  }

  // ================= gizmo =================
  _buildGizmo() {
    this.gizmo = new THREE.Group();
    this.gizmo.visible = false;
    this.gizmo.renderOrder = 999;
    const dirs = { x: new THREE.Vector3(1, 0, 0), y: new THREE.Vector3(0, 1, 0), z: new THREE.Vector3(0, 0, 1) };
    this.gizmoHandles = [];
    for (const [axis, dir] of Object.entries(dirs)) {
      const mat = new THREE.MeshBasicMaterial({ color: AXIS_COLORS[axis], depthTest: false, transparent: true, opacity: 0.95 });
      const handle = new THREE.Group();
      const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.045, 1.0, 8), mat);
      shaft.position.y = 0.5;
      // arrow head for move, cube cap for scale (cap swapped in _syncGizmo)
      const head = new THREE.Mesh(new THREE.ConeGeometry(0.14, 0.34, 12), mat);
      head.position.y = 1.15;
      head.name = 'head-move';
      const cap = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.22, 0.22), mat);
      cap.position.y = 1.12;
      cap.name = 'head-scale';
      handle.add(shaft, head, cap);
      handle.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
      handle.userData.axis = axis;
      handle.traverse((o) => { o.userData.axis = axis; o.renderOrder = 999; });
      this.gizmo.add(handle);
      this.gizmoHandles.push(handle);
    }
    this.scene.add(this.gizmo);
  }

  _syncGizmo() {
    const part = this.selId && this.world.parts.get(this.selId);
    const active = part && (this.tool === 'move' || this.tool === 'scale');
    this.gizmo.visible = !!active;
    if (!active) return;
    this.gizmo.position.set(part.x, part.y, part.z);
    const dist = this.camera.position.distanceTo(this.gizmo.position);
    const s = Math.max(1.2, dist * 0.09);
    this.gizmo.scale.setScalar(s);
    for (const h of this.gizmoHandles) {
      h.getObjectByName('head-move').visible = this.tool === 'move';
      h.getObjectByName('head-scale').visible = this.tool === 'scale';
    }
  }

  // param along axis where the mouse ray lands (camera-facing plane trick)
  _axisParam(e, origin, axisDir) {
    this.raycaster.setFromCamera(this._ndc(e), this.camera);
    const camDir = new THREE.Vector3();
    this.camera.getWorldDirection(camDir);
    const n = new THREE.Vector3().crossVectors(axisDir, new THREE.Vector3().crossVectors(axisDir, camDir));
    if (n.lengthSq() < 1e-8) return null;
    n.normalize();
    const plane = new THREE.Plane().setFromNormalAndCoplanarPoint(n, origin);
    const hit = new THREE.Vector3();
    if (!this.raycaster.ray.intersectPlane(plane, hit)) return null;
    return hit.sub(origin).dot(axisDir);
  }

  _gizmoPick(e) {
    this.raycaster.setFromCamera(this._ndc(e), this.camera);
    const hits = this.raycaster.intersectObjects(this.gizmoHandles, true);
    for (const h of hits) if (h.object.visible && h.object.userData.axis) return h.object.userData.axis;
    return null;
  }

  _startGizmoDrag(e, axis) {
    const part = this.world.parts.get(this.selId);
    if (!part) return;
    const dir = { x: new THREE.Vector3(1, 0, 0), y: new THREE.Vector3(0, 1, 0), z: new THREE.Vector3(0, 0, 1) }[axis];
    const origin = new THREE.Vector3(part.x, part.y, part.z);
    const t0 = this._axisParam(e, origin, dir);
    if (t0 === null) return;
    this.undoStack.push({ kind: 'update', part: { ...part } });
    this.gizmoDrag = { axis, dir, origin, t0, start: { ...part } };
  }

  _updateGizmoDrag(e, final = false) {
    const d = this.gizmoDrag;
    if (!d) return;
    const t = this._axisParam(e, d.origin, d.dir);
    if (t === null) return;
    let delta = t - d.t0;
    const part = { ...this.world.parts.get(this.selId) };
    if (!part.id) return;
    const ax = d.axis, sKey = 's' + ax;
    if (this.tool === 'move') {
      part[ax] = this._snapV(d.start[ax] + delta);
    } else {
      // scale: dragged face follows the handle, opposite face stays anchored
      const newSize = Math.max(0.2, this._snapV(d.start[sKey] + delta));
      const grow = newSize - d.start[sKey];
      part[sKey] = newSize;
      part[ax] = d.start[ax] + grow / 2;
    }
    const now = performance.now();
    if (final || now - this._lastOpSend > 60) {
      this._lastOpSend = now;
      this._opUpdate(part, false);
      this._select(part.id, false);
    }
  }

  // ================= networking =================
  _connect() {
    this.ws = openWS();
    this.ws.onopen = () => this.ws.send(JSON.stringify({ t: 'studio', gameId: this.gameId }));
    this.ws.onclose = () => {
      if (this.alive) { toast('Studio disconnected', 'red'); this.exit(); }
    };
    this.ws.onmessage = (ev) => {
      let msg;
      try { msg = JSON.parse(ev.data); } catch (e) { return; }
      this._handle(msg);
    };
  }

  _send(msg) {
    if (this.ws && this.ws.readyState === 1) this.ws.send(JSON.stringify(msg));
  }

  _handle(msg) {
    switch (msg.t) {
      case 'error':
        toast(msg.error, 'red');
        break;
      case 'sjoined': {
        this.selfId = msg.selfId;
        this.meta = msg.meta;
        this.config = msg.config;
        this.isOwner = msg.isOwner;
        this.world.load(msg.world.parts);
        this.root.querySelector('#st-gamename').textContent = msg.meta.name;
        for (const ed of msg.editors) if (ed.id !== this.selfId) this._addEditor(ed);
        this._renderEditors();
        this._renderConfig();
        this._renderExplorer();
        break;
      }
      case 'sjoin':
        this._addEditor(msg.editor);
        this._renderEditors();
        toast(`${msg.editor.username} joined Studio`);
        break;
      case 'sleave': {
        const ed = this.editors.get(msg.id);
        if (ed && ed.highlightMesh) this.scene.remove(ed.highlightMesh);
        this.editors.delete(msg.id);
        this._renderEditors();
        break;
      }
      case 'sel': {
        const ed = this.editors.get(msg.id);
        if (ed) { ed.sel = msg.partId; this._updateRemoteHighlight(ed); }
        break;
      }
      case 'op':
        this._applyRemoteOp(msg.op);
        break;
      case 'opok':
        if (msg.op.kind === 'add' && this._lastLocalAdd && msg.op.part.id !== this._lastLocalAdd) {
          this.world.removePart(this._lastLocalAdd);
          this.world.addPart(msg.op.part);
          this._lastLocalAdd = null;
          this._renderExplorer();
        }
        break;
      case 'chat': {
        const log = this.root.querySelector('#studio-chat-log');
        const div = document.createElement('div');
        div.innerHTML = `<b>${esc(msg.username)}:</b> ${esc(msg.text)}`;
        log.appendChild(div);
        while (log.children.length > 40) log.firstChild.remove();
        log.scrollTop = log.scrollHeight;
        break;
      }
    }
  }

  _addEditor(ed) {
    this.editors.set(ed.id, Object.assign({ highlightMesh: null }, ed));
    this._updateRemoteHighlight(this.editors.get(ed.id));
  }

  _renderEditors() {
    let html = '';
    for (const ed of this.editors.values()) {
      html += `<span class="editor-chip"><span class="dot" style="background:${ed.color}"></span>${esc(ed.username)}</span>`;
    }
    this.editorsEl.innerHTML = html || '<span style="color:var(--dim);font-size:12px">solo session</span>';
  }

  _updateRemoteHighlight(ed) {
    if (ed.highlightMesh) { this.scene.remove(ed.highlightMesh); ed.highlightMesh = null; }
    if (!ed.sel) return;
    const part = this.world.parts.get(ed.sel);
    if (!part) return;
    const box = new THREE.Box3(
      new THREE.Vector3(part.x - part.sx / 2 - 0.05, part.y - part.sy / 2 - 0.05, part.z - part.sz / 2 - 0.05),
      new THREE.Vector3(part.x + part.sx / 2 + 0.05, part.y + part.sy / 2 + 0.05, part.z + part.sz / 2 + 0.05)
    );
    ed.highlightMesh = new THREE.Box3Helper(box, new THREE.Color(ed.color));
    this.scene.add(ed.highlightMesh);
  }

  _applyRemoteOp(op) {
    if (op.kind === 'add' || op.kind === 'update') {
      this.world.addPart(op.part);
      if (this.selId === op.part.id) this._select(op.part.id);
    } else if (op.kind === 'del') {
      this.world.removePart(op.partId);
      if (this.selId === op.partId) this._select(null);
    } else if (op.kind === 'meta') {
      this.meta = { name: op.data.name, desc: op.data.desc, genre: op.data.genre, public: op.data.public };
      this.config = op.data.config;
      this.root.querySelector('#st-gamename').textContent = op.data.name;
      this._renderConfig();
    }
    for (const ed of this.editors.values()) this._updateRemoteHighlight(ed);
    this._renderExplorer();
  }

  // ================= ops =================
  _opAdd(part) {
    this._lastLocalAdd = part.id;
    this.world.addPart(part);
    this._send({ t: 'op', op: { kind: 'add', part } });
    this.undoStack.push({ kind: 'del', partId: part.id });
    this._renderExplorer();
  }

  _opUpdate(part, recordUndo = true) {
    if (recordUndo) {
      const prev = this.world.parts.get(part.id);
      if (prev) this.undoStack.push({ kind: 'update', part: { ...prev } });
    }
    this.world.addPart(part);
    this._send({ t: 'op', op: { kind: 'update', part } });
    this._renderExplorer();
  }

  _opDel(partId) {
    const prev = this.world.parts.get(partId);
    if (prev) this.undoStack.push({ kind: 'add', part: { ...prev } });
    this.world.removePart(partId);
    this._send({ t: 'op', op: { kind: 'del', partId } });
    if (this.selId === partId) this._select(null);
    this._renderExplorer();
  }

  _undo() {
    const op = this.undoStack.pop();
    if (!op) return;
    if (op.kind === 'add') { this.world.addPart(op.part); this._send({ t: 'op', op }); }
    else if (op.kind === 'update') { this.world.addPart(op.part); this._send({ t: 'op', op }); if (this.selId === op.part.id) this._select(this.selId, false); }
    else if (op.kind === 'del') { this.world.removePart(op.partId); this._send({ t: 'op', op }); this._select(null); }
    this._renderExplorer();
  }

  _duplicate() {
    const src = this.selId && this.world.parts.get(this.selId);
    if (!src) return;
    const copy = { ...src, id: 'c' + Math.random().toString(36).slice(2, 9), x: src.x + src.sx + 0.5 };
    this._opAdd(copy);
    this._select(copy.id);
  }

  _focusSelected() {
    const part = this.selId && this.world.parts.get(this.selId);
    if (!part) return;
    const span = Math.max(part.sx, part.sy, part.sz);
    const off = Math.max(8, span * 1.8);
    this.camPos.set(part.x + off * 0.7, part.y + off * 0.6, part.z + off * 0.7);
    const dir = new THREE.Vector3(part.x, part.y, part.z).sub(this.camPos).normalize();
    this.camYaw = Math.atan2(-dir.x, -dir.z);
    this.camPitch = Math.asin(dir.y);
  }

  // ================= explorer =================
  _renderExplorer() {
    clearTimeout(this._expT);
    this._expT = setTimeout(() => {
      const q = (this.root.querySelector('#st-explorer-q').value || '').toLowerCase();
      const defs = Object.fromEntries(PART_DEFS.map((d) => [d.type, d]));
      const parts = [...this.world.parts.values()]
        .filter((p) => !q || p.type.includes(q) || p.id.toLowerCase().includes(q))
        .sort((a, b) => a.type.localeCompare(b.type) || a.id.localeCompare(b.id));
      let html = '';
      for (const p of parts.slice(0, 400)) {
        const d = defs[p.type] || { label: p.type, color: '#888' };
        html += `<div class="exp-row${p.id === this.selId ? ' sel' : ''}" data-id="${p.id}">
          <span class="exp-chip" style="background:${p.color || d.color}"></span>
          <span class="exp-name">${esc(d.label)}</span>
          <span class="exp-id">${esc(p.id)}</span>
        </div>`;
      }
      if (parts.length > 400) html += `<div class="exp-row" style="color:var(--dim)">… ${parts.length - 400} more</div>`;
      this.explorerEl.innerHTML = html || '<div style="color:var(--dim);padding:6px">No parts</div>';
      this.explorerEl.querySelectorAll('.exp-row[data-id]').forEach((row) => {
        row.onclick = () => this._select(row.dataset.id);
        row.ondblclick = () => { this._select(row.dataset.id); this._focusSelected(); };
      });
      this.root.querySelector('#sts-parts').textContent = `${this.world.parts.size} parts`;
    }, 40);
  }

  // ================= selection & props =================
  _select(partId, sync = true) {
    this.selId = partId;
    if (sync) this._send({ t: 'sel', partId });
    const part = partId ? this.world.parts.get(partId) : null;
    if (this.moverPath) { this.scene.remove(this.moverPath); this.moverPath = null; }
    if (!part) {
      this.selId = null;
      this.selBox.visible = false;
      this.propsEl.innerHTML = '<div style="color:var(--dim)">Nothing selected</div>';
      this.root.querySelector('#sts-sel').textContent = 'nothing selected';
      this.root.querySelector('#rb-sel-info').innerHTML = '<span class="rb-caption">Selection</span>';
      this._renderExplorer();
      return;
    }
    this.selBox.visible = true;
    if (part.type === 'mover') {
      const g = new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3(part.x, part.y, part.z),
        new THREE.Vector3(part.x + part.dx, part.y + part.dy, part.z + part.dz),
      ]);
      this.moverPath = new THREE.Line(g, new THREE.LineBasicMaterial({ color: 0x9b59b6, depthTest: false }));
      this.moverPath.renderOrder = 998;
      this.scene.add(this.moverPath);
    }
    const def = PART_DEFS.find((d) => d.type === part.type);
    this.root.querySelector('#sts-sel').textContent = `${def ? def.label : part.type} (${part.id})`;
    this.root.querySelector('#rb-sel-info').innerHTML =
      `<span class="rb-sel-name"><span class="exp-chip" style="background:${part.color}"></span>${esc(def ? def.label : part.type)}</span><span class="rb-caption">Selection</span>`;
    this._renderProps(part);
    this._renderExplorer();
  }

  _renderProps(part) {
    const num = (name, val, step = 0.5) =>
      `<input type="number" data-prop="${name}" value="${val}" step="${step}">`;
    let extra = '';
    if (part.type === 'mover') {
      extra = `<div class="prop-sec">Mover Path (offset)</div><div class="prop-grid">
        ${num('dx', part.dx ?? 0)}${num('dy', part.dy ?? 0)}${num('dz', part.dz ?? 0)}</div>
        <label class="fld">Period (s)${num('period', part.period ?? 4, 0.5)}</label>`;
    } else if (part.type === 'tele') {
      extra = `<label class="fld">Channel (pairs teleporters)${num('channel', part.channel ?? 1, 1)}</label>`;
    } else if (part.type === 'checkpoint') {
      extra = `<label class="fld">Stage number${num('stage', part.stage ?? 1, 1)}</label>`;
    }
    const swatches = COLOR_PALETTE.map((c) =>
      `<span class="swatch${c === part.color ? ' sel' : ''}" data-color="${c}" style="background:${c}"></span>`).join('');
    this.propsEl.innerHTML = `
      <div class="prop-sec">Position</div>
      <div class="prop-grid">${num('x', part.x)}${num('y', part.y)}${num('z', part.z)}</div>
      <div class="prop-sec">Size</div>
      <div class="prop-grid">${num('sx', part.sx)}${num('sy', part.sy)}${num('sz', part.sz)}</div>
      <div class="prop-sec">Color</div>
      <div class="color-swatches">${swatches}</div>
      ${extra}
      <button class="btn red" style="margin-top:12px;width:100%" id="prop-del">${icon('trash', 13)} Delete part</button>
    `;
    this.propsEl.querySelectorAll('input[data-prop]').forEach((inp) => {
      inp.addEventListener('change', () => {
        const p = { ...this.world.parts.get(part.id) };
        if (!p.id) return;
        p[inp.dataset.prop] = Number(inp.value);
        this._opUpdate(p);
        this._select(p.id);
      });
      inp.addEventListener('keydown', (e) => e.stopPropagation());
    });
    this.propsEl.querySelectorAll('.swatch').forEach((sw) => {
      sw.onclick = () => {
        const p = { ...this.world.parts.get(part.id) };
        p.color = sw.dataset.color;
        this._opUpdate(p);
        this._select(p.id);
      };
    });
    this.propsEl.querySelector('#prop-del').onclick = () => this._opDel(part.id);
  }

  // ================= config panel =================
  _renderConfig() {
    const m = this.meta, c = this.config;
    this.configEl.innerHTML = `
      <label class="fld">Name<input type="text" id="cfg-name" value="${esc(m.name)}" maxlength="50"></label>
      <label class="fld">Description<textarea id="cfg-desc" rows="3" maxlength="1000">${esc(m.desc)}</textarea></label>
      <label class="fld">Genre<select id="cfg-genre">${GENRES.map((g) => `<option${g === m.genre ? ' selected' : ''}>${g}</option>`).join('')}</select></label>
      <label class="fld">Game mode<select id="cfg-mode">${MODES.map((x) => `<option${x === c.mode ? ' selected' : ''}>${x}</option>`).join('')}</select></label>
      <label class="fld">Max players per server<input type="number" id="cfg-max" value="${c.maxPlayers}" min="1" max="50"></label>
      <label class="fld">Gravity<input type="number" id="cfg-grav" value="${c.gravity}" min="5" max="200"></label>
      <label class="fld">Walk speed<input type="number" id="cfg-walk" value="${c.walkSpeed}" min="4" max="40"></label>
      <label class="fld">Jump power<input type="number" id="cfg-jump" value="${c.jumpPower}" min="5" max="60"></label>
      <label class="fld">Respawn time (s)<input type="number" id="cfg-respawn" value="${c.respawnTime}" min="0" max="10" step="0.5"></label>
      <label class="fld" style="display:flex;align-items:center;gap:8px">
        <input type="checkbox" id="cfg-public" style="width:auto"${m.public ? ' checked' : ''}> Public (listed on Discover)
      </label>
      <button class="btn green" style="width:100%" id="cfg-save">Save config</button>
    `;
    this.configEl.querySelectorAll('input,textarea,select').forEach((el) =>
      el.addEventListener('keydown', (e) => e.stopPropagation()));
    this.configEl.querySelector('#cfg-save').onclick = () => {
      const g = (id) => this.configEl.querySelector(id);
      this._send({
        t: 'op',
        op: {
          kind: 'meta',
          data: {
            name: g('#cfg-name').value,
            desc: g('#cfg-desc').value,
            genre: g('#cfg-genre').value,
            public: g('#cfg-public').checked,
            config: {
              mode: g('#cfg-mode').value,
              maxPlayers: Number(g('#cfg-max').value),
              gravity: Number(g('#cfg-grav').value),
              walkSpeed: Number(g('#cfg-walk').value),
              jumpPower: Number(g('#cfg-jump').value),
              respawnTime: Number(g('#cfg-respawn').value),
            },
          },
        },
      });
      toast('Config saved');
    };
  }

  // ================= input / camera =================
  _bindInput() {
    this._onKeyDown = (e) => {
      if (/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)) return;
      this.keys[e.code] = true;
      if (e.code === 'Digit1') this.setTool('select');
      if (e.code === 'Digit2') this.setTool('move');
      if (e.code === 'Digit3') this.setTool('scale');
      if (e.code === 'Digit4') this.setTool('delete');
      if (e.code === 'Escape') {
        if (this.tool === 'place' || this.tool === 'delete') this.setTool('select');
        else this._select(null);
      }
      if (e.code === 'KeyF') this._focusSelected();
      if (e.code === 'Delete' || e.code === 'Backspace') { if (this.selId) this._opDel(this.selId); }
      if (e.code === 'KeyZ' && (e.ctrlKey || e.metaKey)) { e.preventDefault(); this._undo(); }
      if (e.code === 'KeyD' && (e.ctrlKey || e.metaKey)) { e.preventDefault(); this._duplicate(); }
    };
    this._onKeyUp = (e) => { this.keys[e.code] = false; };
    addEventListener('keydown', this._onKeyDown);
    addEventListener('keyup', this._onKeyUp);

    let lookDrag = false, lx = 0, ly = 0, downAt = 0, downBtn = -1;
    this.canvas.addEventListener('mousedown', (e) => {
      lx = e.clientX; ly = e.clientY; downAt = Date.now(); downBtn = e.button;
      if (e.button === 2) { lookDrag = true; return; }
      if (e.button === 0 && (this.tool === 'move' || this.tool === 'scale') && this.selId) {
        const axis = this._gizmoPick(e);
        if (axis) { this._startGizmoDrag(e, axis); return; }
      }
    });
    addEventListener('mouseup', (e) => {
      lookDrag = false;
      if (this.gizmoDrag) {
        this._updateGizmoDrag(e, true);
        this.gizmoDrag = null;
        return;
      }
      if (Date.now() - downAt > 280 || Math.hypot(e.clientX - lx, e.clientY - ly) > 6) return;
      if (e.target !== this.canvas || downBtn !== 0) return;
      if (this.tool === 'select' || this.tool === 'move' || this.tool === 'scale') {
        const hit = this._pickPart(e);
        this._select(hit ? hit.id : null);
      } else if (this.tool === 'delete') {
        const hit = this._pickPart(e);
        if (hit) this._opDel(hit.id);
      } else if (this.tool === 'place' && this.ghost) {
        const def = PART_DEFS.find((d) => d.type === this.placeType);
        const part = {
          id: 'c' + Math.random().toString(36).slice(2, 9),
          type: def.type,
          x: this.ghost.position.x, y: this.ghost.position.y, z: this.ghost.position.z,
          sx: def.size[0], sy: def.size[1], sz: def.size[2],
          color: def.color,
        };
        if (def.type === 'mover') Object.assign(part, { dx: 6, dy: 0, dz: 0, period: 4 });
        if (def.type === 'tele') part.channel = 1;
        if (def.type === 'checkpoint') {
          part.stage = 1 + [...this.world.parts.values()].filter((p) => p.type === 'checkpoint').length;
        }
        this._opAdd(part);
      }
    });
    addEventListener('mousemove', (e) => {
      const dx = e.clientX - lx, dy = e.clientY - ly;
      if (lookDrag) {
        this.camYaw -= dx * 0.005;
        this.camPitch = Math.min(1.4, Math.max(-1.4, this.camPitch - dy * 0.005));
        lx = e.clientX; ly = e.clientY;
        return;
      }
      lx = e.clientX; ly = e.clientY;
      if (this.gizmoDrag) { this._updateGizmoDrag(e); return; }
      if (this.tool === 'place') this._updateGhost(e);
      else if (this.tool === 'move' || this.tool === 'scale') {
        // hover feedback on gizmo handles
        const axis = this.selId ? this._gizmoPick(e) : null;
        this.canvas.style.cursor = axis ? 'grab' : 'default';
      }
    });
    this.canvas.addEventListener('contextmenu', (e) => e.preventDefault());
    this.canvas.addEventListener('wheel', (e) => {
      const dir = new THREE.Vector3();
      this.camera.getWorldDirection(dir);
      this.camPos.addScaledVector(dir, -e.deltaY * 0.02);
      e.preventDefault();
    }, { passive: false });
  }

  _ndc(e) {
    const r = this.canvas.getBoundingClientRect();
    return new THREE.Vector2(
      ((e.clientX - r.left) / r.width) * 2 - 1,
      -((e.clientY - r.top) / r.height) * 2 + 1
    );
  }

  _pickPart(e) {
    this.raycaster.setFromCamera(this._ndc(e), this.camera);
    const hits = this.raycaster.intersectObjects([...this.world.meshes.values()]);
    for (const h of hits) {
      if (!h.object.isMesh) continue;
      let o = h.object;
      while (o && !o.userData.part) o = o.parent;
      if (o && o.userData.part) return o.userData.part;
    }
    return null;
  }

  _rayToPlane(e, planeY) {
    this.raycaster.setFromCamera(this._ndc(e), this.camera);
    const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), -planeY);
    const out = new THREE.Vector3();
    return this.raycaster.ray.intersectPlane(plane, out) ? out : null;
  }

  _updateGhost(e) {
    const def = PART_DEFS.find((d) => d.type === this.placeType);
    if (!this.ghost || this.ghost.userData.type !== def.type) {
      if (this.ghost) this.scene.remove(this.ghost);
      this.ghost = createPartMesh({
        id: '_ghost', type: def.type,
        x: 0, y: 0, z: 0,
        sx: def.size[0], sy: def.size[1], sz: def.size[2],
        color: def.color, dx: 0, dy: 0, dz: 0, period: 4,
      });
      this.ghost.userData.type = def.type;
      this.ghost.traverse((o) => {
        if (!o.material) return;
        const fade = (m) => { const c = m.clone(); c.transparent = true; c.opacity = 0.5; return c; };
        o.material = Array.isArray(o.material) ? o.material.map(fade) : fade(o.material);
      });
      this.scene.add(this.ghost);
    }
    this.raycaster.setFromCamera(this._ndc(e), this.camera);
    const hits = this.raycaster.intersectObjects([...this.world.meshes.values()]);
    let hit = null, hitPoint = null;
    for (const h of hits) {
      if (!h.object.isMesh) continue;
      let o = h.object;
      while (o && !o.userData.part) o = o.parent;
      if (o && o.userData.part) { hit = o.userData.part; hitPoint = h.point; break; }
    }
    let x, y, z;
    if (hit) {
      x = hitPoint.x; z = hitPoint.z;
      y = hit.y + hit.sy / 2 + def.size[1] / 2;
    } else {
      const pt = this._rayToPlane(e, 0);
      if (!pt) return;
      x = pt.x; z = pt.z;
      y = def.size[1] / 2;
    }
    this.ghost.position.set(this._snapV(x), this._snapV(y), this._snapV(z));
  }

  // ================= loop =================
  _loop() {
    let last = performance.now();
    let statusT = 0;
    const animate = (now) => {
      if (!this.alive) return;
      this.raf = requestAnimationFrame(animate);
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      this.resizeFn();

      const speed = (this.keys.ShiftLeft ? 40 : 18) * dt;
      const fwd = new THREE.Vector3(-Math.sin(this.camYaw), 0, -Math.cos(this.camYaw));
      const right = new THREE.Vector3(-fwd.z, 0, fwd.x);
      const active = document.activeElement;
      if (!/INPUT|TEXTAREA|SELECT/.test(active.tagName) && !this.gizmoDrag) {
        if (this.keys.KeyW) this.camPos.addScaledVector(fwd, speed);
        if (this.keys.KeyS) this.camPos.addScaledVector(fwd, -speed);
        if (this.keys.KeyA) this.camPos.addScaledVector(right, -speed);
        if (this.keys.KeyD) this.camPos.addScaledVector(right, speed);
        if (this.keys.KeyE || this.keys.Space) this.camPos.y += speed;
        if (this.keys.KeyQ || this.keys.ControlLeft) this.camPos.y -= speed;
      }
      this.camera.position.copy(this.camPos);
      this.camera.rotation.set(0, 0, 0);
      this.camera.rotateY(this.camYaw);
      this.camera.rotateX(this.camPitch);

      this.world.tick(dt, null);
      this._syncGizmo();

      if (this.selId) {
        const part = this.world.parts.get(this.selId);
        if (part) {
          const c = this.world.partCenter(part);
          this.selBox.box.set(
            new THREE.Vector3(c.x - part.sx / 2, c.y - part.sy / 2, c.z - part.sz / 2),
            new THREE.Vector3(c.x + part.sx / 2, c.y + part.sy / 2, c.z + part.sz / 2)
          );
        }
      }

      statusT += dt;
      if (statusT > 0.25) {
        statusT = 0;
        this.root.querySelector('#sts-cam').textContent =
          `cam ${this.camPos.x.toFixed(0)}, ${this.camPos.y.toFixed(0)}, ${this.camPos.z.toFixed(0)}`;
      }

      this.renderer.render(this.scene, this.camera);
    };
    this.raf = requestAnimationFrame(animate);
  }

  exit(to) {
    if (!this.alive) return;
    this.alive = false;
    cancelAnimationFrame(this.raf);
    removeEventListener('keydown', this._onKeyDown);
    removeEventListener('keyup', this._onKeyUp);
    try { this.ws.close(); } catch (e) {}
    this.renderer.dispose();
    this.onExit(to);
  }
}
